'use strict';
(()=>{
 const model=window.AtlasEvaluation,tr=x=>typeof x==='string'?x:x?.[window.AtlasLanguage.current()]||x?.en||'',t=(zh,en)=>window.AtlasLanguage.current()==='zh'?zh:en;
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let current=[],context={},mode='resources',choices={},extras=[],different=false;
 const names={task:['任务目标','Task objective'],observation:['观测接口','Observation'],action:['动作接口','Actions'],metrics:['原始评价指标','Native metrics'],controls:['配置与预算','Configuration & budget'],limits:['适用范围','Scope']};
 const missing=()=>t('此范围尚无已整理的原始任务协议','No documented task protocol in this scope');
 function options(id){return window.AtlasResearchArchives.get(id).tasks.filter(p=>p.origin!=='arena-documented-candidate'&&(!context.gameId||p.gameIds.includes(context.gameId)));}
 function read(){const p=new URLSearchParams(location.search);mode=p.get('compareMode')==='tasks'?'tasks':'resources';different=p.get('compareDiff')==='1';try{choices=JSON.parse(p.get('compareTasks')||'{}');if(!choices||Array.isArray(choices)||typeof choices!=='object')choices={};extras=JSON.parse(p.get('compareExtras')||'[]');if(!Array.isArray(extras))extras=[];}catch{choices={};extras=[];}extras=extras.filter(id=>current.includes(id)).slice(0,Math.max(0,4-current.length));}
 function sync(){const u=new URL(location.href);u.searchParams.set('compareMode',mode);u.searchParams.set('compareTasks',JSON.stringify(choices));u.searchParams.set('compareExtras',JSON.stringify(extras));if(different)u.searchParams.set('compareDiff','1');else u.searchParams.delete('compareDiff');history.replaceState({},'',u);}
 function slots(){const occurrences={};return [...current,...extras].slice(0,4).map((id,i)=>{const a=window.AtlasResearchArchives.get(id),opts=options(id),key=id+':'+(occurrences[id]||0);occurrences[id]=(occurrences[id]||0)+1;const p=opts.find(u=>u.id===choices[key])||opts.find(u=>context.question&&u.capabilities.some(c=>c.id===context.question.cap))||opts[0]||null;return {id,a,opts,key,p};});}
 const pairs=rows=>{const out=[];for(let i=0;i<rows.length;i++)for(let j=i+1;j<rows.length;j++)if(rows[i].p&&rows[j].p)out.push({a:rows[i],b:rows[j],relation:model.pair(rows[i].p.id,rows[j].p.id)});return out;};
 function resourceRows(){return [
 [t('研究用途','Research use'),s=>s.a.overview?.sections.find(x=>x.key==='research')?.body||s.a.bibliography.scope||s.a.profile.research?.fit||null],
 [t('任务与环境','Tasks & environment'),s=>s.a.overview?.sections.find(x=>x.key==='task')?.body||s.a.profile.research?.scope||null],
 [t('评价方式','Evaluation'),s=>s.a.overview?.sections.find(x=>x.key==='evaluation')?.body||s.a.bibliography.metrics||null],
 [t('适用范围','Scope'),s=>s.a.overview?.sections.find(x=>x.key==='scope')?.body||s.a.bibliography.limits||null],
 [t('Agent 使用记录','Documented agent use'),s=>s.a.bibliography.agents.join(' / ')],
 [t('可进一步对比的协议','Protocols available for comparison'),s=>String(s.opts.length)]];}
 function taskRows(){return [...Object.entries(names).map(([k,n])=>[t(...n),s=>s.p?.[k]||null]),[t('协议版本','Protocol version'),s=>s.p?.protocolDetails?.version||null],[t('终止条件','Termination'),s=>s.p?.protocolDetails?.termination||null],[t('步数 / 局数预算','Step / episode budget'),s=>s.p?.protocolDetails?.budget||null],[t('研究问题','Research question'),s=>{const q=s.p?model.get(s.p.id)?.question:null;return /^(按任务目标确定研究问题|Define the question from the task objective)[。.]?$/.test(tr(q).trim())?null:q;}],[t('主要干扰因素','Principal confounds'),s=>s.p?model.get(s.p.id)?.confounds:null]];}

 const localized=x=>window.AtlasLanguage.text?.(tr(x))||tr(x);
 function compact(value){const full=tr(value);if(!full)return `<span class="comparison-unspecified">${t('未整理','Not documented')}</span>`;const sentences=full.match(/[^。！？]+[。！？]?|.+/g)||[full];let lead=sentences[0];if(window.AtlasLanguage.current()==='en')lead=full.match(/^.*?[.!?](?:\s|$)/)?.[0]||full;const limit=window.AtlasLanguage.current()==='zh'?120:240;if(lead.length>limit)lead=lead.slice(0,limit)+'…';if(lead.trim()===full.trim())return esc(full);return `<details class="compare-cell-detail"><summary><span class="compare-cell-preview">${esc(lead)}</span> <span class="compare-cell-toggle"><span class="when-closed">${t('展开','More')}</span><span class="when-open">${t('收起','Less')}</span></span></summary><p>${esc(full.startsWith(lead.trim())?full.slice(lead.trim().length).trim():full)}</p></details>`;}
 function missingCell(s){return `<span class="comparison-unspecified" title="${esc(s.p?t('查阅配置与来源','Consult configuration and sources'):missing())}">${t('未整理','Not structured')}</span>`;}
 function missingNote(ss,rows){return ss.some(s=>rows.filter(([name,value])=>!(name===t('研究问题','Research question')&&ss.every(item=>!tr(value(item))))&&(!different||new Set(ss.map(item=>JSON.stringify(value(item)))).size>1)).some(([,value])=>!tr(value(s))))?`<p class="comparison-field-note">${t('“未整理”表示本站尚未结构化该字段；原始信息见协议与来源。','“Not structured” means Atlas has not structured this field; consult the source protocols and references.')}</p>`:'';}
 function columnHead(s,i,primary){return `<th scope="col"><strong>${esc(s.a.bibliography.name)}</strong>${primary?`<small>${esc(s.a.bibliography.year)}</small>${mode==='tasks'?`<label class="comparison-task-picker"><span class="sr-only">${t('选择具体协议','Select a protocol')}</span><select data-comparison-task="${esc(s.key)}" aria-label="${esc(s.a.bibliography.name)} ${t('具体任务','task')} ${i+1}">${s.opts.map(p=>`<option value="${esc(p.id)}" ${s.p?.id===p.id?'selected':''}>${esc(tr(p.label))}</option>`).join('')||`<option>${missing()}</option>`}</select></label>`:''}<div class="comparison-column-actions">${i<current.length?`<button data-compare="${s.id}">${t('移出','Remove')} ×</button>`:`<button data-comparison-remove-extra="${i-current.length}">${t('移出任务列','Remove task column')} ×</button>`}${mode==='tasks'&&s.opts.length>1&&slots().length<4?`<button data-comparison-extra="${s.id}">${t('增加任务列','Add task column')}</button>`:''}</div>`:''}</th>`;}
 function table(ss,rows,{primary=false,resource=false}={}){
 const combined=[];
 for(const [name,value] of rows){
  if(name===t('研究问题','Research question')&&ss.every(s=>!tr(value(s))))continue;
  const signature=JSON.stringify(ss.map(s=>tr(value(s)).trim()));
  const previous=combined.find(r=>r.signature===signature&&ss.some(s=>tr(value(s))));
  if(previous)previous.labels.push(name);else combined.push({labels:[name],value,signature});
 }
 rows=combined.map(r=>[r.labels.join(' / '),r.value]);
 rows=rows.filter(([,value])=>!different||new Set(ss.map(s=>JSON.stringify(value(s)))).size>1);return `<div class="compare-table-wrap"><table class="compare-table protocol-comparison"><thead><tr><th scope="col">${t('对比字段','Comparison field')}</th>${ss.map((s,i)=>columnHead(s,i,primary)).join('')}</tr></thead><tbody>${rows.map(([name,value])=>`<tr><th scope="row">${name}</th>${ss.map(s=>`<td>${tr(value(s))?(resource?compact(value(s)):esc(tr(value(s)))):missingCell(s)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${ss.length+1}">${t('这些字段相同；关闭筛选可查看。','These fields match; disable the filter to view them.')}</td></tr>`}</tbody></table></div>`;}
 function conclusions(ss){const relations=pairs(ss),reviewed=relations.filter(x=>x.relation.type!=='unreviewed'),pending=relations.filter(x=>x.relation.type==='unreviewed');
 if(!reviewed.length)return `<details class="comparison-pending-summary"><summary>${relations.length?t(`尚无专项组合分析 · ${pending.length} 组任务关系`,`No curated suite analysis · ${pending.length} task pairs`):t('选择两个任务可查看组合关系','Select two tasks to inspect their relationship')}</summary><p>${t('下表保留各任务的原始协议，可据此比较实验条件。','Compare the source protocols and experimental conditions below.')}</p>${pending.length?`<ul>${pending.map(({a,b})=>`<li>${esc(a.a.bibliography.name)} · ${esc(tr(a.p.label))} × ${esc(b.a.bibliography.name)} · ${esc(tr(b.p.label))}</li>`).join('')}</ul>`:''}</details>`;
 return `<section class="comparison-conclusions"><h3>${t('选型结论','Selection guidance')}</h3>${reviewed.map(({a,b,relation:r})=>`<article><header><strong>${esc(tr(model.relationTypes[r.type]))||t('待判断','Not reviewed')}</strong><h4>${esc(a.a.bibliography.name)} × ${esc(b.a.bibliography.name)}</h4></header><div class="comparison-task-names">${esc(tr(a.p.label))} × ${esc(tr(b.p.label))}</div><p>${esc(tr(r.summary))}</p>${r.difference?`<dl><div><dt>${t('关键差异','Key difference')}</dt><dd>${esc(tr(r.difference))}</dd></div><div><dt>${t('组合建议','Suite recommendation')}</dt><dd>${esc(tr(r.recommendation))}</dd></div></dl>`:''}</article>`).join('')||`<p>${relations.length?t('当前所选任务尚无专项关系分析，可先比较下方协议。','No curated relationship is available for the selected tasks. Compare their protocols below.'):t('选择两个具体任务查看关系。','Choose two concrete tasks to inspect their relationship.')}</p>`}${pending.length?`<details class="comparison-pending"><summary>${t(`${pending.length} 组关系待整理`,`${pending.length} relationships not reviewed`)}</summary><ul>${pending.map(({a,b,relation:r})=>`<li>${esc(tr(a.p.label))} × ${esc(tr(b.p.label))}<p>${esc(tr(r.summary))}</p></li>`).join('')}</ul></details>`:''}<small>${t('基于当前所选协议的编辑分析','Editorial analysis of the selected protocols')}</small></section>`;}
 function sourcePanel(ss){return `<details class="comparison-section comparison-source-panel"><summary>${t('来源','Sources')}</summary><div class="comparison-source-grid" style="--compare-columns:${ss.length}">${ss.map(s=>`<section><h4>${esc(s.a.bibliography.name)}</h4><p><a href="?lang=${window.AtlasLanguage.current()}&view=explore&detail=${s.id}${mode==='tasks'&&s.p?'&archiveTab=protocol&task='+encodeURIComponent(s.p.id):''}">${t('打开来源档案','Open source archive')} ↗</a></p>${mode==='tasks'&&s.p?`<button data-arena-add-protocol="${esc(s.p.id)}">${t('加入 Arena 组合','Add to Arena')} →</button>`:''}<div class="comparison-source-links">${[...new Map((mode==='tasks'?s.p?.evidence||[]:s.a.overview?.sources||s.a.sources.slice(0,2)).map(e=>[e.url,e])).values()].map(e=>`<a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(localized(e.title))} ↗</a>`).join('')}</div></section>`).join('')}</div></details>`;}
 function renderHTML(){const ss=mode==='tasks'?slots():slots().slice(0,current.length),all=taskRows(),find=label=>all.find(([name])=>name===label);const essential=[find(t('研究问题','Research question')),find(t('任务目标','Task objective')),find(t('原始评价指标','Native metrics')),find(t('适用范围','Scope')),find(t('主要干扰因素','Principal confounds'))],technical=all.filter(row=>!essential.includes(row)),primaryMissing=missingNote(ss,essential);return `<button class="modal-close" data-close="compare-dialog" aria-label="${t('关闭对比','Close comparison')}">×</button>${window.AtlasLanguage.picker()}<h2 id="compare-title">${t('Benchmark 选型与任务对比','Benchmark selection & task comparison')}</h2>${context.question?`<p>${esc(tr(context.question.label))}</p>`:''}<div class="comparison-controls"><div>${[['resources',t('资源选型','Resource selection')],['tasks',t('任务协议','Task protocols')]].map(([id,name])=>`<button data-comparison-mode="${id}" aria-pressed="${mode===id}" class="${mode===id?'active':''}">${name}</button>`).join('')}</div><label><input id="comparison-differences" type="checkbox" ${different?'checked':''}> ${t('隐藏相同字段','Hide identical fields')}</label><button id="share-compare">${t('复制对比链接','Copy comparison link')}</button></div><input class="compare-share-url" id="compare-link" aria-label="${t('对比链接','Comparison link')}" readonly hidden value="${esc(location.href)}">${!ss.length?`<p>${t('从目录选择研究资源加入对比。','Select research resources from the directory.')}</p>`:mode==='tasks'?`${conclusions(ss)}${table(ss,essential,{primary:true})}<details class="comparison-section"><summary>${t('接口、配置与复现条件','Interfaces, configuration & reproduction')}</summary>${table(ss,technical)}${primaryMissing?'':missingNote(ss,technical)}</details>${primaryMissing}${sourcePanel(ss)}`:`${table(ss,resourceRows(),{primary:true,resource:true})}${missingNote(ss,resourceRows())}${sourcePanel(ss)}`}`;}
 function paint(){const active=document.activeElement,id=active?.id,modeKey=active?.dataset.comparisonMode,taskKey=active?.dataset.comparisonTask;const root=document.querySelector('#compare-content');root.innerHTML=renderHTML();const next=id?root.querySelector('#'+CSS.escape(id)):modeKey?[...root.querySelectorAll('[data-comparison-mode]')].find(b=>b.dataset.comparisonMode===modeKey):taskKey?[...root.querySelectorAll('[data-comparison-task]')].find(b=>b.dataset.comparisonTask===taskKey):null;next?.focus({preventScroll:true});}
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.comparisonMode){mode=b.dataset.comparisonMode;sync();paint();}if(b.dataset.comparisonExtra&&slots().length<4){const id=b.dataset.comparisonExtra,previous=slots().filter(s=>s.id===id),next=options(id).find(p=>!previous.some(s=>s.p?.id===p.id));extras.push(id);if(next)choices[id+':'+previous.length]=next.id;sync();paint();}if(b.hasAttribute('data-comparison-remove-extra')){const at=Number(b.dataset.comparisonRemoveExtra),remaining=slots().filter((s,i)=>i!==current.length+at),occurrences={};extras.splice(at,1);choices={};for(const s of remaining){const key=s.id+':'+(occurrences[s.id]||0);occurrences[s.id]=(occurrences[s.id]||0)+1;if(s.p)choices[key]=s.p.id;}sync();paint();}});
 document.addEventListener('change',e=>{if(e.target.dataset.comparisonTask){choices[e.target.dataset.comparisonTask]=e.target.value;sync();paint();}if(e.target.id==='comparison-differences'){different=e.target.checked;sync();paint();}});
 window.AtlasComparison={render(ids,options={}){current=ids.filter(id=>window.AtlasResearchArchives.get(id));context=options;read();return renderHTML();}};
})();
